export const LANDING_HTML = "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>Pinsite | Web design agency</title>\r\n<meta name=\"description\" content=\"Pinsite designs, builds, and looks after fast, sharp websites for growing businesses.\">\r\n<link rel=\"canonical\" href=\"https://pinsite.agency/\">\r\n<meta name=\"theme-color\" content=\"#ECECE8\">\r\n<link rel=\"icon\" href=\"data:image/svg+xml;base64,\">\r\n<meta property=\"og:type\" content=\"website\">\r\n<meta property=\"og:site_name\" content=\"Pinsite\">\r\n<meta property=\"og:title\" content=\"Pinsite | Web design agency\">\r\n<meta property=\"og:description\" content=\"Fast, sharp websites for businesses that want customers, not compliments. Design, build, brand and care from one small senior team.\">\r\n<meta property=\"og:url\" content=\"https://pinsite.agency/\">\r\n<meta property=\"og:image\" content=\"https://pinsite.agency/og.jpg\">\r\n<meta property=\"og:image:width\" content=\"1200\">\r\n<meta property=\"og:image:height\" content=\"630\">\r\n<meta property=\"og:image:alt\" content=\"Pinsite. Fast, sharp websites for businesses that want customers.\">\r\n<meta name=\"twitter:card\" content=\"summary_large_image\">\r\n<meta name=\"twitter:title\" content=\"Pinsite | Web design agency\">\r\n<meta name=\"twitter:description\" content=\"Fast, sharp websites for businesses that want customers, not compliments.\">\r\n<meta name=\"twitter:image\" content=\"https://pinsite.agency/og.jpg\">\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n<style>\r\n:root{\r\n  --bg:#ECECE8;\r\n  --ink:#141412;\r\n  --dark:#101010;\r\n  --paper:#FAFAF8;\r\n  --accent:#FF3D00;\r\n  --accent-deep:#B51800;\r\n  --amber:#FF8A00;\r\n  --muted:#7C7C76;\r\n  --line:rgba(20,20,18,.12);\r\n  --r-card:22px;\r\n  --d-fast:150ms;\r\n  --d-normal:250ms;\r\n  --d-slow:600ms;\r\n  --ease-out:cubic-bezier(0,0,.2,1);\r\n  --ease-std:cubic-bezier(.2,0,0,1);\r\n  --serif:\"Instrument Serif\",Georgia,serif;\r\n  --sans:\"Inter\",-apple-system,Helvetica,Arial,sans-serif;\r\n}\r\n*{margin:0;padding:0;box-sizing:border-box}\r\nhtml{scroll-behavior:smooth;overflow-x:clip}\r\nbody{\r\n  font-family:var(--sans);\r\n  background:var(--bg);\r\n  color:var(--ink);\r\n  font-size:16px;\r\n  line-height:1.55;\r\n  -webkit-font-smoothing:antialiased;\r\n  overflow-x:hidden;\r\n}\r\n::selection{background:var(--accent);color:#fff}\r\n.wrap{max-width:1240px;margin:0 auto;padding:0 28px}\r\nem,.it{font-family:var(--serif);font-style:italic;font-weight:400;letter-spacing:0}\r\n\r\n/* ---------- streak art (signature element) ---------- */\r\n.streak{position:relative;overflow:hidden;background:#0d0d0d}\r\n.streak i{position:absolute;border-radius:999px;filter:blur(26px);opacity:.95;display:block}\r\n.streak .s1{width:96%;height:16%;left:2%;top:45%;background:linear-gradient(90deg,transparent,var(--accent-deep) 20%,var(--accent) 55%,var(--amber) 80%,transparent)}\r\n.streak .s2{width:72%;height:6%;left:14%;top:50%;background:linear-gradient(90deg,transparent,#fff 40%,#ffd9c2 72%,transparent);filter:blur(10px);opacity:.9}\r\n.streak .s3{width:40%;height:30%;right:-12%;top:28%;background:radial-gradient(closest-side,rgba(255,61,0,.35),transparent 70%)}\r\n.streak .s4{width:46%;height:36%;left:-14%;bottom:-10%;background:radial-gradient(closest-side,rgba(181,24,0,.35),transparent 70%)}\r\n@keyframes drift{0%{transform:translateX(-3%) scaleX(1)}50%{transform:translateX(3%) scaleX(1.06)}100%{transform:translateX(-3%) scaleX(1)}}\r\n.streak .s1,.streak .s2{animation:drift 12s var(--ease-std) infinite}\r\n.streak .s2{animation-duration:16s}\r\n.streak.silver{background:#c9c9c4}\r\n.streak.silver .s3{background:radial-gradient(closest-side,rgba(255,255,255,.7),transparent 70%)}\r\n.streak.silver .s4{background:radial-gradient(closest-side,rgba(20,20,18,.35),transparent 70%)}\r\n\r\n/* ---------- nav (liquid glass pill) ---------- */\r\n.nav{position:fixed;top:14px;left:0;right:0;z-index:50;padding:0 20px}\r\n.nav-in{\r\n  display:flex;align-items:center;justify-content:space-between;height:76px;\r\n  max-width:1180px;margin:0 auto;padding:0 12px 0 28px;\r\n  border-radius:999px;position:relative;\r\n  background:linear-gradient(180deg,rgba(252,252,250,.55),rgba(252,252,250,.32));\r\n  -webkit-backdrop-filter:blur(18px) saturate(1.6);\r\n  backdrop-filter:blur(18px) saturate(1.6);\r\n  border:1px solid rgba(255,255,255,.55);\r\n  box-shadow:0 10px 30px -14px rgba(20,20,18,.28),inset 0 1px 0 rgba(255,255,255,.7),inset 0 -1px 0 rgba(20,20,18,.05);\r\n  transition:background var(--d-normal) var(--ease-std),box-shadow var(--d-normal) var(--ease-std);\r\n}\r\n.nav-in::before{content:\"\";position:absolute;inset:0;border-radius:inherit;pointer-events:none;\r\n  background:radial-gradient(60% 130% at 18% 0%,rgba(255,255,255,.5),transparent 55%)}\r\n.nav.scrolled .nav-in{\r\n  background:linear-gradient(180deg,rgba(252,252,250,.78),rgba(252,252,250,.55));\r\n  box-shadow:0 14px 34px -14px rgba(20,20,18,.35),inset 0 1px 0 rgba(255,255,255,.8),inset 0 -1px 0 rgba(20,20,18,.06);\r\n}\r\n.nav-in .btn{padding:13px 26px}\r\n.logo{font-weight:700;font-size:19px;letter-spacing:-.03em;text-decoration:none;color:var(--ink)}\r\n.logo b{color:var(--accent);font-weight:700}\r\n.nav-links{display:flex;gap:30px;list-style:none}\r\n.nav-links a{color:var(--ink);text-decoration:none;font-size:14px;font-weight:500;position:relative;padding:4px 0}\r\n.nav-links a::after{content:\"\";position:absolute;left:0;bottom:0;height:1.5px;width:0;background:var(--accent);transition:width var(--d-fast) var(--ease-out)}\r\n.nav-links a:hover::after,.nav-links a:focus-visible::after{width:100%}\r\n.btn{\r\n  display:inline-flex;align-items:center;gap:10px;\r\n  padding:13px 24px;border-radius:999px;border:1px solid var(--ink);\r\n  background:transparent;color:#fff;font-family:var(--sans);font-size:14px;font-weight:600;\r\n  text-decoration:none;cursor:pointer;position:relative;overflow:hidden;isolation:isolate;\r\n  transition:border-color var(--d-fast) var(--ease-out),color var(--d-fast) var(--ease-out),transform var(--d-fast) var(--ease-out);\r\n}\r\n.btn::after{content:\"\";position:absolute;inset:0;background:var(--ink);border-radius:inherit;z-index:-2;transition:background var(--d-fast) var(--ease-out)}\r\n.btn::before{content:\"\";position:absolute;left:-18%;top:-45%;width:66%;height:190%;z-index:-1;\r\n  background:radial-gradient(50% 50% at 50% 50%,rgba(255,61,0,.9),rgba(181,24,0,.45) 60%,transparent 76%);\r\n  filter:blur(15px);transition:transform .55s var(--ease-std);\r\n}\r\n.btn:hover{border-color:var(--accent);transform:translateY(-1px)}\r\n.btn:hover::before{transform:translateX(170%)}\r\n.btn:active{transform:translateY(0)}\r\n.btn.ghost{color:var(--ink)}\r\n.btn.ghost::before,.btn.ghost::after{display:none}\r\n.btn.ghost:hover{border-color:var(--accent);color:var(--accent);background:rgba(255,61,0,.06)}\r\n.btn .arr{transition:transform var(--d-fast) var(--ease-out)}\r\n.btn:hover .arr{transform:translateX(3px)}\r\n.btn:focus-visible,.nav-links a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\r\n\r\n/* ---------- hero ---------- */\r\n.hero{padding-top:150px;position:relative}\r\n.eyebrow{\r\n  display:inline-flex;align-items:center;gap:8px;\r\n  font-size:12px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);\r\n}\r\n.eyebrow::before{content:\"\";width:7px;height:7px;border-radius:50%;background:var(--accent)}\r\n.hero h1{\r\n  font-size:clamp(70px,10.9vw,156px);line-height:1.02;letter-spacing:-.035em;font-weight:600;\r\n  max-width:12ch;margin-top:22px;\r\n}\r\n.hero h1 .swap{display:inline-block}\r\n.hero h1 .sww{\r\n  display:inline-block;\r\n  padding:.24em .14em;margin:-.24em -.14em;\r\n  font-family:var(--serif);font-style:italic;font-weight:400;letter-spacing:0;\r\n  /* glossy glass: bright reflection across the top, a faint specular line through the middle, deep colour at the base, soft glow underneath. no strokes */\r\n  background-image:\r\n    linear-gradient(180deg,rgba(255,255,255,.82) 0%,rgba(255,255,255,.32) 24%,rgba(255,255,255,0) 44%,rgba(255,255,255,0) 49%,rgba(255,255,255,.22) 50%,rgba(255,255,255,.05) 57%,rgba(255,255,255,0) 68%),\r\n    linear-gradient(180deg,#FF7A3D 0%,#F0350A 55%,#8E1000 100%);\r\n  -webkit-background-clip:text;background-clip:text;\r\n  color:transparent;-webkit-text-fill-color:transparent;\r\n  filter:drop-shadow(0 16px 34px rgba(240,53,10,.34)) drop-shadow(0 3px 8px rgba(240,53,10,.18));\r\n  transition:transform .28s var(--ease-out),opacity .28s var(--ease-out);\r\n}\r\n.hero h1 .sww.out{transform:translateY(-.5em);opacity:0}\r\n.hero h1 .sww.in{transform:translateY(.5em);opacity:0}\r\n.hero-sub{max-width:46ch;color:var(--muted);font-size:10px;margin-top:24px}\r\n.hero-cta{display:flex;gap:12px;margin-top:clamp(64px,9vw,110px);flex-wrap:wrap}\r\n.hero-grid{display:grid;grid-template-columns:1fr auto;gap:40px;align-items:start}\r\n\r\n/* hero spacing to marquee */\r\n.hero{padding-bottom:70px}\r\n\r\n/* ---------- marquee (tilted ribbon) ---------- */\r\n.marquee-wrap{overflow:hidden;margin:14px 0 34px;padding:14px 0}\r\n.marquee{background:var(--ink);overflow:hidden;padding:16px 0;white-space:nowrap;\r\n  transform:rotate(-2deg);width:104%;margin-left:-2%}\r\n.marquee-track{display:inline-flex;animation:marq 60s linear infinite;will-change:transform}\r\n.mq{display:inline-flex;align-items:center;gap:40px;padding-right:40px;\r\n  font-size:19px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--paper)}\r\n.mq em{font-family:var(--serif);font-style:italic;font-weight:400;text-transform:none;font-size:25px;letter-spacing:0;color:var(--amber)}\r\n.mq b{color:var(--accent);font-weight:700;font-size:20px}\r\n@keyframes marq{from{transform:translateX(0)}to{transform:translateX(-50%)}}\r\n\r\n/* ---------- reveal system ---------- */\r\n[data-reveal]{opacity:0;transform:translateY(26px);transition:opacity var(--d-slow) var(--ease-out),transform var(--d-slow) var(--ease-out)}\r\n[data-reveal].in{opacity:1;transform:none}\r\n[data-stagger]>*{opacity:0;transform:translateY(26px);transition:opacity var(--d-slow) var(--ease-out),transform var(--d-slow) var(--ease-out)}\r\n[data-stagger].in>*{opacity:1;transform:none}\r\n[data-stagger].in>*:nth-child(1){transition-delay:0ms}\r\n[data-stagger].in>*:nth-child(2){transition-delay:70ms}\r\n[data-stagger].in>*:nth-child(3){transition-delay:140ms}\r\n[data-stagger].in>*:nth-child(4){transition-delay:210ms}\r\n[data-stagger].in>*:nth-child(5){transition-delay:280ms}\r\n\r\n/* ---------- section dividers (sheet overlay) ---------- */\r\nsection.curve,footer.curve{position:relative;padding-top:120px}\r\n.curve::after{\r\n  content:\"\";position:absolute;top:-56px;left:0;right:0;height:56px;\r\n  background:var(--bg);border-radius:0 0 28px 28px;\r\n  box-shadow:0 18px 30px -14px rgba(20,20,18,.38);pointer-events:none;\r\n}\r\n/* deep arc variant */\r\nsection.arc,footer.arc{position:relative;padding-top:130px}\r\n.arc::after{\r\n  content:\"\";position:absolute;top:-92px;left:-12%;right:-12%;height:92px;\r\n  background:var(--bg);border-radius:0 0 50% 50%/0 0 92px 92px;\r\n  box-shadow:0 16px 28px -16px rgba(20,20,18,.32);pointer-events:none;\r\n}\r\n\r\n/* ---------- statement ---------- */\r\n.statement{padding:130px 0 110px;text-align:center}\r\n.statement .eyebrow{justify-content:center}\r\n.statement h2{\r\n  font-size:clamp(26px,3.3vw,44px);line-height:1.28;letter-spacing:-.02em;font-weight:600;\r\n  max-width:24ch;margin:26px auto 0;\r\n}\r\n.pill{\r\n  display:inline-block;width:1.9em;height:.74em;border-radius:999px;vertical-align:-0.06em;\r\n  background:linear-gradient(100deg,#1a0c07 0%,var(--accent-deep) 30%,var(--accent) 58%,var(--amber) 82%,#ffd9c2 100%);\r\n  box-shadow:inset 0 0 10px rgba(255,255,255,.25);\r\n  position:relative;overflow:hidden;\r\n}\r\n\r\n.statement .note{font-size:13px;color:var(--muted);margin-top:22px}\r\n\r\n/* ---------- services ---------- */\r\n.services{padding:20px 0 110px}\r\n.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;row-gap:40px;align-items:start}\r\n.svc{\r\n  --fill:#3F3129;--on:#F4F4F0;\r\n  background:var(--fill);color:var(--on);\r\n  border-radius:0 var(--r-card) var(--r-card) var(--r-card);\r\n  aspect-ratio:5/4;display:flex;flex-direction:column;justify-content:flex-end;\r\n  padding:22px 0 20px 18px;position:relative;min-width:0;container-type:inline-size;\r\n  filter:drop-shadow(0 5px 6px rgba(20,20,18,.30)) drop-shadow(0 18px 20px rgba(20,20,18,.20));\r\n  transition:transform var(--d-normal) var(--ease-out),filter var(--d-normal) var(--ease-out);\r\n}\r\n/* folder tab, same colour as the folder */\r\n.svc::before{content:\"\";position:absolute;top:-15px;left:0;width:44%;height:19px;border-radius:12px 12px 0 0;background:var(--fill)} /* a touch taller than the gap so it never shows a seam when it lifts */\r\n.svc:hover{transform:translateY(-6px);filter:drop-shadow(0 8px 8px rgba(20,20,18,.30)) drop-shadow(0 28px 26px rgba(20,20,18,.24))}\r\n.svc .tag{\r\n  position:absolute;top:18px;left:18px;font-size:12px;font-weight:600;\r\n  padding:6px 13px;border-radius:999px;border:1px solid currentColor;opacity:.85;z-index:2;\r\n}\r\n/* title sized to span the folder, ending short of the right edge */\r\n.svc>div{position:relative;z-index:2;width:100%}\r\n.svc h3{font-size:52px;font-size:clamp(20px,var(--tsize,24cqw),120px);font-weight:600;letter-spacing:-.035em;line-height:1;white-space:nowrap}\r\n/* each title is sized to its own word length so they all end at the same margin */\r\n.svc.f1{--tsize:17cqw}\r\n.svc.f2{--tsize:15.2cqw}\r\n.svc.f3{--tsize:22.3cqw}\r\n.svc.f4{--tsize:18.9cqw}\r\n/* one brown or grey per folder */\r\n.svc.f1{--fill:#3F3129}\r\n.svc.f2{--fill:#7B5F49}\r\n.svc.f3{--fill:#5B5B56}\r\n.svc.f4{--fill:#C6C1B8;--on:var(--ink)}\r\n.svc:nth-child(2){margin-top:56px}\r\n.svc:nth-child(3){margin-top:20px}\r\n.svc:nth-child(4){margin-top:76px}\r\n\r\n/* ---------- results: six blocks of type, big and small, laid like uneven bricks into one rectangle. no cards, no lines ---------- */\r\n.results{padding:0 0 120px}\r\n.results .proc-head{margin-bottom:36px}\r\n/* hairline grid: the grid background shows through 1px gaps, so every brick is a drawn rectangle and the six of them make one bigger one */\r\n.res-grid{display:grid;grid-template-columns:repeat(4,1fr);grid-template-areas:\"seo seo week care\" \"seo seo leads leads\" \"speed speed speed done\";gap:1px;background:var(--line);border:1px solid var(--line);align-items:stretch}\r\n.res{position:relative;display:flex;flex-direction:column;justify-content:flex-start;gap:6px;min-width:0;container-type:inline-size;background:var(--bg);padding:26px 28px 24px;min-height:190px;transition:background var(--d-normal) var(--ease-out);\r\n  --nfade:linear-gradient(180deg,#141412 0%,#141412 38%,#4A3A30 72%,#9A948B 100%)}\r\n.res .n{font-size:var(--big,64px);font-weight:600;letter-spacing:-.045em;line-height:.95;display:block;font-variant-numeric:tabular-nums}\r\n.res .n em{font-family:var(--serif);font-style:italic;font-weight:400;color:var(--accent);letter-spacing:0;font-size:.5em;white-space:nowrap;display:block;margin-top:.1em}\r\n.res .cap{font-size:14px;color:var(--muted);line-height:1.4;white-space:nowrap;margin-top:auto;padding-top:14px}\r\n.res:hover{background:var(--paper)}\r\n.res.seo{grid-area:seo;--big:min(38cqw,190px)}\r\n.res.speed{grid-area:speed;--big:min(17cqw,120px)}\r\n.res.speed .n em,.res.leads .n em{display:inline;margin:0 0 0 .12em}\r\n.res.leads{grid-area:leads;--big:min(21cqw,104px)}\r\n.res.week{grid-area:week;--big:min(30cqw,76px)}\r\n.res.care{grid-area:care;--big:min(30cqw,76px)}\r\n.res.done{grid-area:done;--big:min(28cqw,72px)}\r\n.res.done .n em{font-size:.4em}\r\n/* the numbers carry the same top-to-bottom fade as the titles; on the rolling ones it goes on each digit so the strips keep it */\r\n.res .odo.rolled>span:not(.dg){color:var(--ink);-webkit-text-fill-color:var(--ink)}\r\n.res .n>span:not(.odo),.res .odo:not(.rolled),.res .odo.rolled .dg i span{\r\n  background-image:var(--nfade);background-size:100% 1em;background-repeat:no-repeat;\r\n  -webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}\r\n/* rolling digits: each digit is a strip of 0-9 twice, it spins one full turn then lands on the real number */\r\n.odo .dg{display:inline-block;height:1em;overflow:hidden;vertical-align:top;line-height:1}\r\n.odo .dg i{display:block;font-style:normal;transform:translateY(0);transition:transform 1.5s cubic-bezier(.2,.8,.2,1)}\r\n.odo .dg i span{display:block;height:1em;line-height:1}\r\n.odo.go .dg i{transform:translateY(calc(var(--d) * -1em))}\r\n\r\n/* services folders open a little on hover: tab lifts, a sheet of paper peeks out */\r\n.svc::before{transition:transform .25s var(--ease-out)}\r\n.svc::after{content:\"\";position:absolute;left:47%;right:14px;top:-12px;height:12px;border-radius:5px 5px 0 0;background:#F4F4F0;opacity:.92;transform:scaleY(0);transform-origin:bottom;transition:transform .25s var(--ease-out)}\r\n.svc:hover::before{transform:translateY(-3px)}\r\n.svc:hover::after{transform:scaleY(1)}\r\n\r\n/* ---------- sheets: FAQ, privacy, terms and cookies slide up over the site like a sheet, on #questions #privacy #terms #cookies ---------- */\r\n.sheet-backdrop{display:none;position:fixed;inset:0;z-index:70;background:rgba(20,20,18,.55);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);animation:sheetfade .35s var(--ease-out) both}\r\nbody.sheet-open .sheet-backdrop{display:block}\r\nhtml.sheet-open,body.sheet-open{overflow:hidden}\r\n.page{display:none;position:fixed;left:50%;bottom:0;z-index:80;width:min(980px,100%);max-height:92dvh;max-height:92vh;overflow:auto;overscroll-behavior:contain;\r\n  background:var(--bg);border-radius:28px 28px 0 0;box-shadow:0 -30px 80px -30px rgba(20,20,18,.6);padding:0 0 60px;\r\n  animation:sheetup .55s cubic-bezier(.2,.8,.2,1) both;transform:translateX(-50%)}\r\n.page.active{display:block}\r\n@keyframes sheetup{from{transform:translate(-50%,100%)}to{transform:translate(-50%,0)}}\r\n@keyframes sheetfade{from{opacity:0}to{opacity:1}}\r\n.sheet-bar{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:14px 22px 10px;background:linear-gradient(180deg,var(--bg) 70%,rgba(236,236,232,0))}\r\n.sheet-bar::before{content:\"\";position:absolute;left:50%;top:8px;width:44px;height:4px;border-radius:999px;background:rgba(20,20,18,.18);transform:translateX(-50%)}\r\n.sheet-close{width:40px;height:40px;border-radius:50%;border:1px solid var(--line);background:var(--paper);color:var(--ink);font:400 22px/1 var(--sans);cursor:pointer;display:grid;place-items:center;transition:background var(--d-fast) var(--ease-out),color var(--d-fast) var(--ease-out)}\r\n.sheet-close:hover{background:var(--ink);color:#fff;border-color:var(--ink)}\r\n.page .pwrap{max-width:760px;margin:0 auto;padding:30px 28px 0}\r\n.page-back{display:none}\r\n.page-back{display:flex;width:fit-content;align-items:center;gap:8px;font-size:14px;font-weight:500;color:var(--ink);text-decoration:none;padding:9px 16px;border:1px solid var(--ink);border-radius:999px;margin-bottom:40px;transition:background var(--d-fast) var(--ease-out),color var(--d-fast) var(--ease-out)}\r\n.page-back:hover{background:var(--ink);color:#fff}\r\n.page .eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\r\n.page h1{font-size:clamp(34px,5vw,56px);letter-spacing:-.03em;font-weight:600;line-height:1.05;margin:14px 0 10px;\r\n  background-image:linear-gradient(180deg,#141412 0%,#141412 38%,#4A3A30 72%,#9A948B 100%);background-repeat:repeat-y;background-size:100% 1.05em;-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}\r\n.page h1 em{-webkit-text-fill-color:var(--accent)}\r\n.page .updated{color:var(--muted);font-size:14px;margin-bottom:48px}\r\n.page .lead{color:#2B2B28;font-size:18px;max-width:56ch;margin-bottom:48px}\r\n.page h2{font-size:22px;letter-spacing:-.02em;font-weight:600;margin:44px 0 12px;scroll-margin-top:110px}\r\n.page .group{font-size:12px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin:64px 0 8px;padding-top:24px;border-top:1px solid var(--line)}\r\n.page .group:first-of-type{margin-top:0;border-top:none;padding-top:0}\r\n.page p,.page li{color:#2B2B28;max-width:64ch;line-height:1.6}\r\n.page p+p{margin-top:12px}\r\n.page ul{padding-left:22px;margin-top:10px}\r\n.page li+li{margin-top:6px}\r\n.page a{color:var(--ink)}\r\n.page mark{background:#FFE7DD;color:inherit;padding:0 4px;border-radius:4px}\r\n.page table{border-collapse:collapse;width:100%;margin-top:14px;font-size:14.5px}\r\n.page th,.page td{text-align:left;padding:10px 12px 10px 0;border-bottom:1px solid var(--line);vertical-align:top;color:#2B2B28}\r\n.page th{font-weight:600;color:var(--ink)}\r\n.page .ask{margin-top:64px;padding:26px 28px;border-radius:18px;background:var(--ink);color:#F4F4F0}\r\n.page .ask h2{margin:0 0 6px;color:#F4F4F0}\r\n.page .ask p{color:rgba(244,244,240,.72)}\r\n.page .ask a{color:#fff;font-weight:600}\r\n.page-foot{margin-top:64px;padding-top:24px;border-top:1px solid var(--line);display:flex;flex-wrap:wrap;gap:8px 22px;font-size:13px}\r\n.page-foot a{color:var(--muted);text-decoration:none}\r\n.page-foot a:hover{color:var(--ink)}\r\n.faq-more{display:inline-flex;align-items:center;gap:8px;margin-top:28px;font-size:14px;font-weight:600;color:var(--ink);text-decoration:none;border-bottom:1px solid var(--ink)}\r\n.faq-more:hover{color:var(--accent);border-color:var(--accent)}\r\n\r\n/* ---------- extra sheet bits: service and company pages, the work grid, the week timeline, the contact form ---------- */\r\n.ask-row{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-top:18px}\r\n.ask .btn.small{margin:0;color:var(--ink);border-color:#F4F4F0}\r\n.ask .btn.small::after{background:#F4F4F0}\r\n.ask .btn.small:hover{color:#fff;border-color:var(--accent)}\r\n.ask .btn.small:hover::after{background:var(--accent)}\r\n.ask-alt{color:rgba(244,244,240,.8)!important;font-weight:500!important;font-size:14px;text-decoration:none;border-bottom:1px solid rgba(244,244,240,.35)}\r\n.ask-alt:hover{color:#fff!important;border-color:#fff}\r\n.work-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:8px}\r\n.work-grid figure{margin:0;border-radius:16px;overflow:hidden;background:var(--paper);border:1px solid var(--line)}\r\n.work-grid img{display:block;width:100%;height:auto;aspect-ratio:16/9;object-fit:cover}\r\n.work-grid figcaption{padding:10px 14px 12px;font-size:13.5px;color:var(--muted)}\r\n.work-grid figcaption b{display:block;font-weight:600;color:var(--ink);font-size:14.5px}\r\n.steps{margin-top:8px}\r\n.stepline{display:grid;grid-template-columns:110px 1fr;gap:18px;padding:22px 0;border-top:1px solid var(--line)}\r\n.stepline:last-child{border-bottom:1px solid var(--line)}\r\n.stepline .day{font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--accent);padding-top:6px}\r\n.stepline h2{margin:0 0 6px}\r\n.cform{display:grid;gap:14px;margin-top:8px;max-width:520px}\r\n.cform label{display:grid;gap:6px;font-size:13px;font-weight:600;color:var(--ink)}\r\n.cform input,.cform select,.cform textarea{font:400 15px/1.4 var(--sans);color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:12px 14px;width:100%;outline:none;transition:border-color var(--d-fast) var(--ease-out),box-shadow var(--d-fast) var(--ease-out)}\r\n.cform input:focus,.cform select:focus,.cform textarea:focus{border-color:var(--ink);box-shadow:0 0 0 3px rgba(20,20,18,.08)}\r\n.cform textarea{resize:vertical;min-height:110px}\r\n.cform .btn{justify-self:start;margin-top:6px}\r\n.cform-note{font-size:13px;color:var(--muted)}\r\n.cform.shake{animation:shake .4s var(--ease-out)}\r\n@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}\r\n.svc-link{position:absolute;inset:-15px 0 0 0;z-index:5;border-radius:inherit;cursor:pointer}\r\n.svc{cursor:pointer}\r\n@media(max-width:600px){.work-grid{grid-template-columns:1fr}.stepline{grid-template-columns:1fr;gap:6px;padding:18px 0}}\r\n\r\n[data-sheet],[data-close]{cursor:pointer}\r\n\r\n/* ---------- the pin mark: used in place of the old asterisk, everywhere ---------- */\r\n.mk{display:inline-block;width:.78em;height:1.05em;background:url(\"data:image/svg+xml;base64,\") center/contain no-repeat;vertical-align:-.16em}\r\n.logo{display:inline-flex;align-items:center;gap:.34em}\r\n.logo .mk{width:1.05em;height:1.42em;vertical-align:0}\r\n.mq .mk{width:16px;height:22px;margin:0 2px}\r\n.big .mark.mk{width:28px;height:38px;display:block;margin:0 auto}\r\n\r\n/* ---------- fading gradient on section titles: solid at the top of the letters, fading to brown then grey at the bottom, with a soft shadow ---------- */\r\n.proc-head h2,.faq-head h2,.big h2,.statement h2{\r\n  background-image:linear-gradient(180deg,#141412 0%,#141412 38%,#4A3A30 72%,#9A948B 100%);\r\n  background-repeat:repeat-y;background-size:100% 1.05em; /* one gradient per line, so every line fades at its own bottom */\r\n  -webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;\r\n  filter:drop-shadow(0 8px 14px rgba(20,20,18,.14));\r\n}\r\n.big h2{background-size:100% 1.06em}\r\n.statement h2{background-size:100% 1.28em}\r\n.faq-head h2{line-height:1.1;background-size:100% 1.1em}\r\n.big h2 em{-webkit-text-fill-color:var(--accent)}\r\n.statement h2 .pill{-webkit-text-fill-color:initial}\r\n/* same idea on the dark card, white at the top fading to orange at the bottom */\r\n.cta-card h2{\r\n  background-image:linear-gradient(180deg,#F4F4F0 0%,#F4F4F0 40%,#FFC9AE 74%,#FF8A00 100%);\r\n  background-repeat:repeat-y;background-size:100% 1.08em;\r\n  -webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;\r\n  filter:drop-shadow(0 8px 16px rgba(0,0,0,.35));\r\n}\r\n\r\n/* ---------- process ---------- */\r\n.process{padding:110px 0;position:relative}\r\n.process::before{content:\"\";position:absolute;left:8%;right:8%;top:40%;height:52%;pointer-events:none;\r\n  background:radial-gradient(42% 60% at 28% 50%,rgba(255,61,0,.16),transparent 70%),radial-gradient(42% 60% at 72% 50%,rgba(255,138,0,.14),transparent 70%);\r\n  filter:blur(44px)}\r\n.proc-head{display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:end;margin-bottom:64px}\r\n.proc-head h2{font-size:clamp(30px,3.6vw,48px);letter-spacing:-.025em;font-weight:600;line-height:1.05}\r\n.proc-head p{color:var(--muted);font-size:15px;max-width:40ch;justify-self:end}\r\n.proc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}\r\n.step{\r\n  position:relative;min-height:256px;padding:22px;border-radius:18px;\r\n  display:flex;flex-direction:column;justify-content:flex-end;\r\n  background:linear-gradient(180deg,rgba(252,252,250,.62),rgba(252,252,250,.36));\r\n  -webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);\r\n  border:1px solid rgba(255,255,255,.6);\r\n  box-shadow:0 14px 30px -20px rgba(20,20,18,.3),inset 0 1px 0 rgba(255,255,255,.7);\r\n  transition:transform var(--d-normal) var(--ease-out),box-shadow var(--d-normal) var(--ease-out);\r\n}\r\n.step:hover{transform:translateY(-4px);box-shadow:0 20px 36px -20px rgba(20,20,18,.38),inset 0 1px 0 rgba(255,255,255,.8)}\r\n.step .num{\r\n  position:absolute;top:-6px;right:12px;\r\n  font-family:var(--serif);font-style:italic;font-size:clamp(96px,9.5vw,142px);line-height:1;\r\n  color:rgba(20,20,18,.09);\r\n  transition:color var(--d-normal) var(--ease-out);\r\n}\r\n.step:hover .num{color:var(--accent)}\r\n.step h3{font-size:17px;font-weight:600}\r\n.step p{font-size:13.5px;color:var(--muted);margin-top:6px;max-width:26ch}\r\n\r\n/* ---------- big statement ---------- */\r\n.big{padding:130px 0;text-align:center}\r\n.big .mark{color:var(--accent);font-size:26px;font-weight:700}\r\n.big h2{\r\n  font-size:clamp(38px,5.6vw,76px);line-height:1.06;letter-spacing:-.035em;font-weight:600;\r\n  max-width:17ch;margin:18px auto 0;\r\n}\r\n.big h2 em{color:var(--accent)}\r\n\r\n/* ---------- cta ---------- */\r\n.cta{padding:0 0 110px}\r\n.cta-card{\r\n  border-radius:28px;padding:90px 40px;text-align:center;color:#F4F4F0;position:relative;overflow:hidden;\r\n}\r\n.cta-card .inner{position:relative;z-index:2}\r\n.cta-card h2{font-size:clamp(30px,4vw,54px);letter-spacing:-.03em;font-weight:600;line-height:1.08}\r\n.cta-card p{color:rgba(244,244,240,.7);margin-top:14px;font-size:16px}\r\n.cta-card .btn{margin-top:30px;color:var(--ink);border-color:#F4F4F0}\r\n.cta-card .btn::before{opacity:.5;filter:blur(18px)}\r\n.cta-card .btn::after{background:#F4F4F0}\r\n.cta-card .btn:hover{color:#fff;border-color:var(--accent)}\r\n.cta-card .btn:hover::after{background:var(--accent)}\r\n.cta-card .s1{top:70%}\r\n.cta-card .s2{top:75%}\r\n.cta-card i{opacity:.8}\r\n\r\n/* ---------- bottom-of-screen progressive blur ---------- */\r\n/* fixed strip along the bottom of the viewport; six stacked layers, 1px up to 8px, each masked to its own slice so the blur ramps in with no seam as content scrolls under it */\r\n.scroll-blur{position:fixed;left:0;right:0;bottom:0;height:72px;z-index:40;pointer-events:none}\r\n.scroll-blur i{position:absolute;inset:0;display:block}\r\n.scroll-blur i:nth-child(1){-webkit-backdrop-filter:blur(1px);backdrop-filter:blur(1px);-webkit-mask-image:linear-gradient(to top,transparent 55%,#000 67%,#000 80%,transparent 100%);mask-image:linear-gradient(to top,transparent 55%,#000 67%,#000 80%,transparent 100%)}\r\n.scroll-blur i:nth-child(2){-webkit-backdrop-filter:blur(2px);backdrop-filter:blur(2px);-webkit-mask-image:linear-gradient(to top,transparent 42%,#000 55%,#000 67%,transparent 80%);mask-image:linear-gradient(to top,transparent 42%,#000 55%,#000 67%,transparent 80%)}\r\n.scroll-blur i:nth-child(3){-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px);-webkit-mask-image:linear-gradient(to top,transparent 30%,#000 42%,#000 55%,transparent 67%);mask-image:linear-gradient(to top,transparent 30%,#000 42%,#000 55%,transparent 67%)}\r\n.scroll-blur i:nth-child(4){-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);-webkit-mask-image:linear-gradient(to top,transparent 18%,#000 30%,#000 42%,transparent 55%);mask-image:linear-gradient(to top,transparent 18%,#000 30%,#000 42%,transparent 55%)}\r\n.scroll-blur i:nth-child(5){-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);-webkit-mask-image:linear-gradient(to top,transparent 6%,#000 18%,#000 30%,transparent 42%);mask-image:linear-gradient(to top,transparent 6%,#000 18%,#000 30%,transparent 42%)}\r\n.scroll-blur i:nth-child(6){-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);-webkit-mask-image:linear-gradient(to top,#000 0%,#000 18%,transparent 30%);mask-image:linear-gradient(to top,#000 0%,#000 18%,transparent 30%)}\r\n@media (max-width:720px){.scroll-blur{height:52px}}\r\n\r\n/* ---------- work ---------- */\r\n.work{padding:110px 0 100px}\r\n.work .proc-head{margin-bottom:54px}\r\n.car{display:grid;gap:20px;overflow:hidden;\r\n  mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);\r\n  -webkit-mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}\r\n.car-row{display:flex;width:max-content;will-change:transform}\r\n.car-set{display:flex;gap:20px;padding-right:20px}\r\n.car-row.left{animation:carL 44s linear infinite}\r\n.car-row.right{animation:carR 50s linear infinite}\r\n@keyframes carL{from{transform:translateX(0)}to{transform:translateX(-50%)}}\r\n@keyframes carR{from{transform:translateX(-50%)}to{transform:translateX(0)}}\r\n.car .proj{flex:none}\r\n.car img.thumb{height:250px;width:auto;display:block}\r\n.car div.thumb{width:380px}\r\n.proj{border-radius:var(--r-card);overflow:hidden}\r\n.proj .thumb{height:250px}\r\n.proj .t1{background:radial-gradient(120% 100% at 82% 8%,rgba(255,61,0,.5),transparent 55%),#101010}\r\n.proj .t2{background:radial-gradient(120% 100% at 18% 90%,rgba(255,138,0,.45),transparent 55%),#1A0D08}\r\n.proj .t3{background:radial-gradient(120% 100% at 80% 85%,rgba(255,61,0,.35),transparent 60%),#C9C9C4}\r\n.proj .t4{background:radial-gradient(120% 100% at 20% 15%,rgba(232,64,20,.4),transparent 55%),#C9C9C4}\r\n.proj .t5{background:radial-gradient(120% 100% at 70% 20%,rgba(181,24,0,.55),transparent 55%),#141412}\r\n\r\n/* ---------- quotes ---------- */\r\n.quotes{padding:110px 0}\r\n.quote-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;row-gap:48px}\r\n.quote{position:relative;background:var(--paper);border:1px solid var(--line);border-radius:var(--r-card);padding:44px 28px 30px;display:flex;flex-direction:column;gap:20px;justify-content:space-between}\r\n.quote::before{content:\"\\201C\";position:absolute;top:-26px;left:50%;transform:translateX(-50%);font-family:var(--serif);font-size:92px;line-height:1;color:var(--ink);pointer-events:none}\r\n.quote p{font-family:var(--serif);font-style:italic;font-size:20px;line-height:1.4}\r\n.quote .who{font-size:13px;color:var(--muted);display:flex;align-items:center;gap:8px}\r\n.quote .who::before{content:\"~\";color:var(--accent);font-weight:700;font-size:15px}\r\n\r\n/* ---------- faq ---------- */\r\n.faq{padding:110px 0}\r\n.faq-head{text-align:center;margin-bottom:44px}\r\n.faq-head h2{font-size:clamp(30px,3.6vw,48px);letter-spacing:-.025em;font-weight:600;margin-top:14px}\r\n.faq-list{max-width:760px;margin:0 auto;border-top:1px solid var(--line)}\r\n.faq details{border-bottom:1px solid var(--line)}\r\n.faq summary{cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 4px;font-weight:600;font-size:17px}\r\n.faq summary::-webkit-details-marker{display:none}\r\n.faq .plus{color:var(--accent);font-size:24px;line-height:1;flex:none;transition:transform var(--d-fast) var(--ease-out)}\r\n.faq details[open] .plus{transform:rotate(45deg)}\r\n.faq details p{padding:0 4px 24px;color:var(--muted);max-width:62ch;font-size:15px}\r\n.faq summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\r\n\r\n/* ---------- footer ---------- */\r\n.footer{padding:80px 0 0}\r\n.foot-grid{display:grid;grid-template-columns:2.2fr 1fr 1fr 1fr;gap:40px;padding-bottom:64px}\r\n.foot-brand p{color:var(--muted);font-size:14px;max-width:30ch;margin-top:14px}\r\n.foot-mail{margin-top:22px;padding:16px 18px;border:1px solid var(--line);border-radius:14px;background:var(--paper);max-width:340px}\r\n.foot-mail-label{display:block;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\r\n.foot-mail a{display:inline-flex;align-items:center;gap:8px;margin-top:6px;font-size:17px;font-weight:600;letter-spacing:-.01em;color:var(--ink);text-decoration:none}\r\n.foot-mail a .arr{transition:transform var(--d-fast) var(--ease-out)}\r\n.foot-mail a:hover{color:var(--accent)}\r\n.foot-mail a:hover .arr{transform:translateX(4px)}\r\n.foot-mail small{display:block;margin-top:4px;font-size:12.5px;color:var(--muted)}\r\n.socials{display:flex;gap:10px;margin-top:18px}\r\n.socials a{width:38px;height:38px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;color:var(--ink);transition:background var(--d-fast) var(--ease-out),color var(--d-fast) var(--ease-out),border-color var(--d-fast) var(--ease-out)}\r\n.socials a:hover,.socials a:focus-visible{background:var(--ink);color:#fff;border-color:var(--ink)}\r\n.socials svg{width:16px;height:16px;fill:currentColor}\r\n.foot-col h3{font-size:12px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:16px}\r\n.foot-col ul{list-style:none;display:grid;gap:10px}\r\n.foot-col a{color:var(--ink);text-decoration:none;font-size:14px}\r\n.foot-col a:hover{color:var(--accent)}\r\n.foot-bar{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;border-top:1px solid var(--line);padding:18px 0;font-size:13px;color:var(--muted)}\r\n.top-link{color:var(--muted);text-decoration:none;font-weight:500}\r\n.top-link:hover{color:var(--ink)}\r\n\r\n/* ---------- endmark (half-cut wordmark) ---------- */\r\n.endmark{position:relative;height:clamp(78px,15.5vw,250px);overflow:hidden;margin-top:4px}\r\n.endmark .glow{position:absolute;inset:0;pointer-events:none;filter:blur(26px);\r\n  background:radial-gradient(40% 52% at 40% 62%,rgba(226,60,20,.8),transparent 70%),radial-gradient(36% 46% at 62% 58%,rgba(255,138,0,.75),transparent 72%);\r\n  animation:drift 22s var(--ease-std) infinite}\r\n.endmark .word{position:absolute;left:50%;top:-.03em;transform:translateX(-50%);z-index:2;font-size:clamp(96px,20vw,320px);line-height:1;font-weight:600;letter-spacing:-.05em;color:#D6D6CF;white-space:nowrap;user-select:none}\r\n\r\n/* ---------- load choreography ---------- */\r\n.load{opacity:0;transform:translateY(24px)}\r\nbody.ready .load{opacity:1;transform:none;transition:opacity .7s var(--ease-out),transform .7s var(--ease-out)}\r\nbody.ready .load.l1{transition-delay:.05s}\r\nbody.ready .load.l2{transition-delay:.13s}\r\nbody.ready .load.l3{transition-delay:.21s}\r\nbody.ready .load.l4{transition-delay:.29s}\r\n\r\n/* ---------- responsive ---------- */\r\n@media(max-width:1000px){\r\n  .svc-grid{grid-template-columns:1fr 1fr}\r\n  .svc:nth-child(n){margin-top:0}\r\n  .res-grid{grid-template-columns:1fr 1fr;grid-auto-rows:auto;grid-template-areas:\"seo seo\" \"week care\" \"leads leads\" \"speed speed\" \"done done\";gap:1px}\r\n  .proc-grid{grid-template-columns:1fr 1fr;row-gap:44px}\r\n  .proc-head{grid-template-columns:1fr}\r\n  .proc-head p{justify-self:start}\r\n  .foot-grid{grid-template-columns:1fr 1fr;row-gap:40px}\r\n}\r\n@media(max-width:760px){\r\n  .nav{top:10px;padding:0 12px}\r\n  .hero h1 .swap{display:block}\r\n  .nav-in{height:64px;padding:0 10px 0 20px}\r\n  .nav-links{display:none}\r\n  .hero{padding-top:120px}\r\n  .hero-grid{grid-template-columns:1fr}\r\n  .proc-grid{grid-template-columns:1fr}\r\n  .cta-card{padding:70px 24px}\r\n  .car img.thumb{height:190px}\r\n  .proj .thumb{height:190px}\r\n  .quote-grid{grid-template-columns:1fr}\r\n  .hero h1{font-size:clamp(46px,15vw,70px)}\r\n  .hero-sub{font-size:15px}\r\n  .hero-cta{margin-top:44px}\r\n  .statement{padding:84px 0 70px}\r\n  .services{padding:20px 0 80px}\r\n  .svc-grid{grid-template-columns:1fr 1fr;gap:14px;row-gap:30px}\r\n  .svc .tag{top:14px;left:14px;padding:5px 11px;font-size:11px}\r\n  .svc{padding:18px 0 16px 14px}\r\n  .res-grid{grid-template-columns:1fr 1fr;grid-auto-rows:auto;grid-template-areas:\"seo seo\" \"week care\" \"leads leads\" \"speed speed\" \"done done\";gap:1px}\r\n  .res{padding:18px 16px 16px;min-height:0}\r\n  .res .cap{padding-top:10px}\r\n  .res .cap{font-size:12.5px;white-space:normal}\r\n  .res.seo{--big:84px}\r\n  .res.speed{--big:64px}\r\n  .res.leads{--big:56px}\r\n  .res.week,.res.care,.res.done{--big:38px}\r\n  .results{padding-bottom:90px}\r\n  .step{min-height:190px}\r\n  .foot-grid{grid-template-columns:1fr 1fr;row-gap:36px}\r\n  .foot-brand{grid-column:1/-1}\r\n}\r\n\r\n/* ---------- reduced motion ---------- */\r\n@media(prefers-reduced-motion:reduce){\r\n  *,[data-reveal],[data-stagger]>*,.load{animation:none!important;transition:none!important;opacity:1!important;transform:none!important;clip-path:none!important}\r\n  .marquee{transform:rotate(-2deg)!important}\r\n  .endmark .word{transform:translateX(-50%)!important}\r\n  .quote::before{transform:translateX(-50%)!important}\r\n  html{scroll-behavior:auto}\r\n}\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<nav class=\"nav\" id=\"nav\">\r\n  <div class=\"nav-in\">\r\n    <a class=\"logo\" href=\"#top\"><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a>\r\n    <ul class=\"nav-links\">\r\n      <li><a href=\"#services\">Services</a></li>\r\n      <li><a href=\"#work\">Work</a></li>\r\n      <li><a href=\"#process\">Process</a></li>\r\n      <li><a href=\"#about\">About</a></li>\r\n    </ul>\r\n    <a class=\"btn ghost\" href=\"#contact\">Contact us</a>\r\n  </div>\r\n</nav>\r\n\r\n<header class=\"hero\" id=\"top\">\r\n  <div class=\"wrap\">\r\n    <div class=\"hero-grid\">\r\n      <div>\r\n        <h1 class=\"load l2\">Tired of <span class=\"swap\" id=\"swapChip\"><i class=\"sww\" id=\"swap\">slow</i></span> websites?</h1>\r\n        <p class=\"hero-sub load l3\">Pinsite designs, builds, and looks after fast, sharp websites for businesses that want customers, not compliments. One team from first sketch to launch day.</p>\r\n        <div class=\"hero-cta load l4\">\r\n          <a class=\"btn\" href=\"#contact\">Start a project <span class=\"arr\">→</span></a>\r\n          <a class=\"btn ghost\" href=\"#services\">See what we do</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</header>\r\n\r\n<main>\r\n<div class=\"marquee-wrap\">\r\n<div class=\"marquee\" aria-hidden=\"true\">\r\n  <div class=\"marquee-track\">\r\n    <span class=\"mq\">Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b> Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b> Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b> Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b></span>\r\n    <span class=\"mq\">Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b> Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b> Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b> Web design <b class=\"mk\" aria-hidden=\"true\"></b> <em>development</em> <b class=\"mk\" aria-hidden=\"true\"></b> Branding <b class=\"mk\" aria-hidden=\"true\"></b> <em>care plans</em> <b class=\"mk\" aria-hidden=\"true\"></b></span>\r\n  </div>\r\n</div>\r\n</div>\r\n\r\n<section class=\"statement\" id=\"about\">\r\n  <div class=\"wrap\" data-reveal>\r\n    <span class=\"eyebrow\">About studio</span>\r\n    <h2>Pinsite is a web design agency of sharp <span class=\"pill\" aria-hidden=\"true\"></span> builders turning business goals into <span class=\"pill\" aria-hidden=\"true\"></span> sites that sell.</h2>\r\n    <p class=\"note\">Small team. Senior work. No handoffs between six departments.</p>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"services\" id=\"services\">\r\n  <div class=\"wrap\">\r\n    <div class=\"svc-grid\" data-stagger>\r\n      <article class=\"svc f1\">\r\n        <a class=\"svc-link\" data-sheet=\"web-design\" role=\"button\" tabindex=\"0\" aria-label=\"Web design, what you get\"></a>\r\n        <span class=\"tag\">Design</span>\r\n        <div><h3>Web design</h3></div>\r\n      </article>\r\n      <article class=\"svc f2\">\r\n        <a class=\"svc-link\" data-sheet=\"development\" role=\"button\" tabindex=\"0\" aria-label=\"Development, what you get\"></a>\r\n        <span class=\"tag\">Build</span>\r\n        <div><h3>Development</h3></div>\r\n      </article>\r\n      <article class=\"svc f3\">\r\n        <a class=\"svc-link\" data-sheet=\"branding\" role=\"button\" tabindex=\"0\" aria-label=\"Branding, what you get\"></a>\r\n        <span class=\"tag\">Brand</span>\r\n        <div><h3>Branding</h3></div>\r\n      </article>\r\n      <article class=\"svc f4\">\r\n        <a class=\"svc-link\" data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\" aria-label=\"Care plans, what you get\"></a>\r\n        <span class=\"tag\">Care</span>\r\n        <div><h3>Care plans</h3></div>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"work curve\" id=\"work\">\r\n  <div class=\"wrap\">\r\n    <div class=\"proc-head\" data-reveal>\r\n      <h2>Recent <em>builds</em></h2>\r\n      <p>Retail, local services, B2B. If it needs to sell, we've built it.</p>\r\n    </div>\r\n  </div>\r\n  <div class=\"car\" data-reveal>\r\n    <div class=\"car-row left\" data-row=\"top\"></div>\r\n    <div class=\"car-row right\" data-row=\"bottom\"></div>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"results\" id=\"results\">\r\n  <div class=\"wrap\">\r\n    <div class=\"proc-head\" data-reveal>\r\n      <h2>Results, <em>not promises</em></h2>\r\n      <p>What every Pinsite project comes with, and what it does once it's live.</p>\r\n    </div>\r\n    <div class=\"res-grid\" data-stagger>\r\n      <div class=\"res seo\"><b class=\"n\"><span class=\"odo\">56</span>% <em>better SEO</em></b><span class=\"cap\">than the sites we replace</span></div>\r\n      <div class=\"res week\"><b class=\"n\"><span class=\"odo\">1</span> <em>week delivery</em></b><span class=\"cap\">kickoff to launch, most projects</span></div>\r\n      <div class=\"res care\"><b class=\"n\"><span class=\"odo\">1</span> <em>year free care</em></b><span class=\"cap\">updates, fixes, monthly report</span></div>\r\n      <div class=\"res leads\"><b class=\"n\"><span class=\"odo\">3</span>x <em>more leads</em></b><span class=\"cap\">in the first 90 days, on average</span></div>\r\n      <div class=\"res speed\"><b class=\"n\"><span class=\"odo\">0.6</span>s <em>load time</em></b><span class=\"cap\">on a phone, after a rebuild</span></div>\r\n      <div class=\"res done\"><b class=\"n\">Done. <em>hosting and legal</em></b><span class=\"cap\">domain, hosting, privacy, terms</span></div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"process arc\" id=\"process\">\r\n  <div class=\"wrap\">\r\n    <div class=\"proc-head\" data-reveal>\r\n      <h2>How we <em>work</em></h2>\r\n      <p>Four steps, fixed timeline, one point of contact. You always know what happens next.</p>\r\n    </div>\r\n    <div class=\"proc-grid\" data-stagger>\r\n      <div class=\"step\">\r\n        <span class=\"num\">01</span>\r\n        <h3>Discover</h3>\r\n        <p>Your goals, your customers, and what the site has to do.</p>\r\n      </div>\r\n      <div class=\"step\">\r\n        <span class=\"num\">02</span>\r\n        <h3>Design</h3>\r\n        <p>Direction, layout, and a clickable preview you approve.</p>\r\n      </div>\r\n      <div class=\"step\">\r\n        <span class=\"num\">03</span>\r\n        <h3>Build</h3>\r\n        <p>Clean code, fast pages, tested on real devices.</p>\r\n      </div>\r\n      <div class=\"step\">\r\n        <span class=\"num\">04</span>\r\n        <h3>Launch &amp; care</h3>\r\n        <p>We go live together, then keep it sharp month after month.</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"quotes\">\r\n  <div class=\"wrap\">\r\n    <div class=\"proc-head\" data-reveal>\r\n      <h2>What clients <em>say</em></h2>\r\n      <p>Short version: the site starts pulling its weight.</p>\r\n    </div>\r\n    <div class=\"quote-grid\" data-stagger>\r\n      <figure class=\"quote\">\r\n        <p>\"I didn't think anyone noticed websites. Two clients brought ours up on calls in the first week. That's never happened to us before.\"</p>\r\n        <figcaption class=\"who\">Founder, logistics company</figcaption>\r\n      </figure>\r\n      <figure class=\"quote\">\r\n        <p>\"I'm not a tech person and I never once felt stupid asking something. They explained it in normal words, did what they said, and it was done when they said it would be.\"</p>\r\n        <figcaption class=\"who\">Owner, coffee brand</figcaption>\r\n      </figure>\r\n      <figure class=\"quote\">\r\n        <p>\"For years I'd tell people to ignore the website and just call us. Now new patients turn up saying they booked because of it.\"</p>\r\n        <figcaption class=\"who\">Clinic director</figcaption>\r\n      </figure>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"faq curve\" id=\"faq\">\r\n  <div class=\"wrap\">\r\n    <div class=\"faq-head\" data-reveal>\r\n      <span class=\"eyebrow\">FAQ</span>\r\n      <h2>Questions we hear a lot</h2>\r\n    </div>\r\n    <div class=\"faq-list\" data-reveal>\r\n      <details>\r\n        <summary>How much does a website cost? <span class=\"plus\">+</span></summary>\r\n        <p>It depends on size and scope. After a short discovery call you get a fixed quote, so the price you approve is the price you pay.</p>\r\n      </details>\r\n      <details>\r\n        <summary>How long does a project take? <span class=\"plus\">+</span></summary>\r\n        <p>Most sites go live within a week of kickoff once the content is ready. Bigger builds take longer, and you get a dated timeline before we start.</p>\r\n      </details>\r\n      <details>\r\n        <summary>What's the difference between design and development? <span class=\"plus\">+</span></summary>\r\n        <p>Design is how the site looks and flows. Development is the code that makes it real. At Pinsite the same team does both, so nothing gets lost in a handoff.</p>\r\n      </details>\r\n      <details>\r\n        <summary>What do we need to give you? <span class=\"plus\">+</span></summary>\r\n        <p>Your logo if you have one, any photos or copy you want to keep, and about an hour a week for feedback. We handle the rest.</p>\r\n      </details>\r\n      <details>\r\n        <summary>Who owns the website? <span class=\"plus\">+</span></summary>\r\n        <p>You do. Domain, code, and content are all in your name from day one.</p>\r\n      </details>\r\n      <details>\r\n        <summary>What happens after launch? <span class=\"plus\">+</span></summary>\r\n        <p>You can take the keys and run it yourself, or stay on a care plan and we keep it updated, fast, and ranking.</p>\r\n      </details>\r\n      <details>\r\n        <summary>Can't AI just build my website? <span class=\"plus\">+</span></summary>\r\n        <p>AI tools can spit out a decent-looking page in minutes, and we use them where they speed us up. What they can't do is know your market, your customers, or why a visitor should pick you. That judgement is the job.</p>\r\n      </details>\r\n    </div>\r\n    <a class=\"faq-more\" data-sheet=\"questions\" role=\"button\" tabindex=\"0\">All the questions we get asked &rarr;</a>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"big\">\r\n  <div class=\"wrap\" data-reveal>\r\n    <span class=\"mark mk\" aria-hidden=\"true\"></span>\r\n    <h2>We build websites that <em>win</em> you customers.</h2>\r\n  </div>\r\n</section>\r\n\r\n<section class=\"cta\" id=\"contact\">\r\n  <div class=\"wrap\">\r\n    <div class=\"cta-card streak\" data-reveal>\r\n      <i class=\"s1\" aria-hidden=\"true\"></i><i class=\"s2\" aria-hidden=\"true\"></i><i class=\"s3\" aria-hidden=\"true\"></i><i class=\"s4\" aria-hidden=\"true\"></i>\r\n      <div class=\"inner\">\r\n        <h2>Ready to move?</h2>\r\n        <p>Tell us about your project. We reply within one business day.</p>\r\n        <a class=\"btn\" href=\"mailto:pinsite74@gmail.com\">Start a project <span class=\"arr\">→</span></a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n</main>\r\n\r\n<footer class=\"footer arc\">\r\n  <div class=\"wrap\">\r\n    <div class=\"foot-grid\">\r\n      <div class=\"foot-brand\">\r\n        <a class=\"logo\" href=\"#top\"><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a>\r\n        <p>A web design agency. Design, build, and care from one small senior team.</p>\r\n        <div class=\"foot-mail\">\r\n          <span class=\"foot-mail-label\">Email us</span>\r\n          <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com <span class=\"arr\">&rarr;</span></a>\r\n          <small>We reply within one business day.</small>\r\n        </div>\r\n        <div class=\"socials\">\r\n          <a href=\"#\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"4.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"17.2\" cy=\"6.8\" r=\"1.4\"/></svg></a>\r\n          <a href=\"#\" aria-label=\"LinkedIn\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M4 9h4v11H4z\"/><circle cx=\"6\" cy=\"5\" r=\"2\"/><path d=\"M11 9h4v2c.7-1.3 2-2.3 4-2.3 3 0 4 2 4 5V20h-4v-5.5c0-1.5-.5-2.5-1.8-2.5-1.4 0-2.2 1-2.2 2.6V20h-4z\"/></svg></a>\r\n          <a href=\"#\" aria-label=\"X\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M3 3h4.6l5 6.6L17.8 3H21l-6.8 8.6L21.4 21h-4.6l-5.4-7-5.6 7H2.6l7.4-9.2z\"/></svg></a>\r\n          <a href=\"#\" aria-label=\"YouTube\"><svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"2.5\" y=\"6\" width=\"19\" height=\"13\" rx=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M10.5 9.7v5.6l4.8-2.8z\"/></svg></a>\r\n        </div>\r\n      </div>\r\n      <div class=\"foot-col\">\r\n        <h3>Services</h3>\r\n        <ul>\r\n          <li><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a></li>\r\n          <li><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a></li>\r\n          <li><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a></li>\r\n          <li><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a></li>\r\n        </ul>\r\n      </div>\r\n      <div class=\"foot-col\">\r\n        <h3>Company</h3>\r\n        <ul>\r\n          <li><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a></li>\r\n          <li><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a></li>\r\n          <li><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a></li>\r\n          <li><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a></li>\r\n          <li><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></li>\r\n        </ul>\r\n      </div>\r\n      <div class=\"foot-col\">\r\n        <h3>Legal</h3>\r\n        <ul>\r\n          <li><a data-sheet=\"privacy\" role=\"button\" tabindex=\"0\">Privacy policy</a></li>\r\n          <li><a data-sheet=\"terms\" role=\"button\" tabindex=\"0\">Terms of service</a></li>\r\n          <li><a data-sheet=\"cookies\" role=\"button\" tabindex=\"0\">Cookie policy</a></li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n    <div class=\"foot-bar\">\r\n      <small>© <span id=\"yr\">2026</span> Pinsite. All rights reserved.</small>\r\n      <a class=\"top-link\" href=\"#top\">Back to top ↑</a>\r\n    </div>\r\n  </div>\r\n  <div class=\"endmark\" aria-hidden=\"true\">\r\n    <span class=\"glow\"></span>\r\n    <span class=\"word\">pinsite</span>\r\n  </div>\r\n</footer>\r\n\r\n<div class=\"sheet-backdrop\" aria-hidden=\"true\"></div>\r\n<div class=\"page\" id=\"web-design\" data-title=\"Web design\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Web design\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Services</span>\r\n    <h1>Web design <em>that sells</em></h1>\r\n    <p class=\"lead\">Interfaces that make choosing you the easy option. Every page has one job: get the visitor to call, book or buy.</p>\r\n    <h2>What you get</h2>\r\n    <ul>\r\n      <li>A site planned around what your customers actually do, not around what looks nice in a pitch.</li>\r\n      <li>Layout, type and colour that look like your business. No template you have seen on three other sites.</li>\r\n      <li>Mobile first, because that is where most of your visitors are.</li>\r\n      <li>Copy written with you from a call or rough notes, not dumped on you as homework.</li>\r\n      <li>A clickable design to poke at on your phone and laptop before a line of code is written.</li>\r\n    </ul>\r\n    <h2>How it goes</h2>\r\n    <p>One call to understand the business, a fixed quote the same day, the design in your hands within two days. One round of changes is included and that is usually all it takes, because most of the thinking happened on the call.</p>\r\n    <h2>Good for</h2>\r\n    <p>Local services, retail, B2B, clinics, restaurants, anyone whose site has to bring in customers rather than just exist.</p>\r\n    <div class=\"ask\">\r\n      <h2>Want one?</h2>\r\n      <p>Tell us what the site has to do and we will come back with a plan and a price.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"builds\" role=\"button\" tabindex=\"0\">See recent builds</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"development\" data-title=\"Development\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Development\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Services</span>\r\n    <h1>Development, <em>done right</em></h1>\r\n    <p class=\"lead\">Responsive, search ready, and built to load fast on any phone. The code is the part nobody sees and everybody feels.</p>\r\n    <h2>What you get</h2>\r\n    <ul>\r\n      <li>Hand written code, no page builder bloat. That is why our sites load in well under a second.</li>\r\n      <li>Tested on real phones and real connections, not just a big monitor in the studio.</li>\r\n      <li>Search engine basics done properly: titles, structure, speed, image sizes, the things that move rankings.</li>\r\n      <li>Forms, bookings, shops, maps, whatever the site needs to do its job.</li>\r\n      <li>An editor for text, images and posts so you can change things without calling us.</li>\r\n    </ul>\r\n    <h2>Speed is the feature</h2>\r\n    <p>A slow site loses people before they read a word. Every build we ship scores in the green on Google's own speed test, on a phone, and we show you the numbers before launch.</p>\r\n    <h2>Already have a design?</h2>\r\n    <p>Send it over. We build from Figma files, sketches or an existing site that just needs rebuilding properly.</p>\r\n    <div class=\"ask\">\r\n      <h2>Need it built?</h2>\r\n      <p>Send what you have, even if it is just a rough idea, and we will scope it.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">How the week goes</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"branding\" data-title=\"Branding\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Branding\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Services</span>\r\n    <h1>Branding <em>that sticks</em></h1>\r\n    <p class=\"lead\">Logo, voice, and a system your whole team can actually use. Not a 90 page brand book that lives in a drawer.</p>\r\n    <h2>What you get</h2>\r\n    <ul>\r\n      <li>A logo with the files you need: colour, mono, small versions, social sizes.</li>\r\n      <li>A colour palette and two typefaces, chosen so they work on screens and on print.</li>\r\n      <li>A one page voice guide: how you sound, what you say, what you never say.</li>\r\n      <li>Templates for the things you make every week: social posts, a proposal, an email signature.</li>\r\n      <li>Everything in one shared folder, organised so anyone can find it.</li>\r\n    </ul>\r\n    <h2>With or without a site</h2>\r\n    <p>Branding usually happens as the first step of a site build, so the two match from day one. It also works on its own if your site is fine and the rest is not.</p>\r\n    <h2>Rebrands</h2>\r\n    <p>If you have a logo people already know, we keep what works and fix what does not. A rebrand should feel like a clean up, not a name change.</p>\r\n    <div class=\"ask\">\r\n      <h2>Ready for a look people remember?</h2>\r\n      <p>Send us your current logo and a line about the business. We will tell you what we would change.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About the studio</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"care-plans\" data-title=\"Care plans\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Care plans\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Services</span>\r\n    <h1>Care plans, <em>year one free</em></h1>\r\n    <p class=\"lead\">Updates, SEO, and a monthly report in plain language. Every site we build comes with a year of it included.</p>\r\n    <h2>What is covered</h2>\r\n    <ul>\r\n      <li>Software updates, security patches and daily backups, checked by a person, not a script.</li>\r\n      <li>Small changes each month: a new photo, a price, a page tweak. Send it, it gets done.</li>\r\n      <li>A speed and search check every month, with fixes made before you notice anything.</li>\r\n      <li>A short monthly report in normal words: what changed, what visitors did, what we suggest next.</li>\r\n      <li>Someone to email who already knows your site.</li>\r\n    </ul>\r\n    <h2>After the first year</h2>\r\n    <p>Carry on month to month at a flat rate, or take the keys and run it yourself. No lock in. If you leave, you get a full copy of the site and every login.</p>\r\n    <h2>Sites we did not build</h2>\r\n    <p>We take those on too, after a quick health check so we know what we are looking after.</p>\r\n    <div class=\"ask\">\r\n      <h2>Want someone looking after it?</h2>\r\n      <p>Tell us about the site and we will send a plan and a monthly price.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"questions\" role=\"button\" tabindex=\"0\">Common questions</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"studio\" data-title=\"About\" role=\"dialog\" aria-modal=\"true\" aria-label=\"About\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Company</span>\r\n    <h1>About <em>the studio</em></h1>\r\n    <p class=\"lead\">Pinsite is a small senior team that designs, builds and looks after websites for businesses that want customers, not compliments.</p>\r\n    <h2>Why small</h2>\r\n    <p>At a big agency your project passes through six departments and a project manager. Something gets lost at every handoff. Here the people on the first call are the people who design it, build it and pick up the phone a year later. Nothing gets lost because nothing gets handed off.</p>\r\n    <h2>How we think</h2>\r\n    <ul>\r\n      <li>A website is a salesperson, not a brochure. It should bring in work.</li>\r\n      <li>Fast beats fancy. Every extra second of loading costs you customers.</li>\r\n      <li>Plain English, always. If we cannot explain a decision simply, it is probably the wrong decision.</li>\r\n      <li>Fixed prices, dated timelines, no surprises at the end.</li>\r\n    </ul>\r\n    <h2>Who we have built for</h2>\r\n    <p>Cosmetics and skincare brands, yoga studios, watch and sneaker stores, dental practices, bakeries, restaurants, clothing and fashion retail, a road works company and a Web3 platform. If it needs to sell, we have probably built one like it.</p>\r\n    <div class=\"ask\">\r\n      <h2>Sound like your kind of people?</h2>\r\n      <p>One email is all it takes to find out.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"builds\" role=\"button\" tabindex=\"0\">See the work</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"builds\" data-title=\"Work\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Work\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Company</span>\r\n    <h1>Recent <em>builds</em></h1>\r\n    <p class=\"lead\">Retail, local services, B2B. A few of the sites that went live recently.</p>\r\n    <div class=\"work-grid\" id=\"workGrid\"></div>\r\n    <div class=\"ask\">\r\n      <h2>Want yours on this list?</h2>\r\n      <p>Tell us what you sell and who buys it. We will take it from there.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">What a build includes</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"how-we-work\" data-title=\"Process\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Process\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Company</span>\r\n    <h1>How we <em>work</em></h1>\r\n    <p class=\"lead\">Four steps, fixed timeline, one point of contact. Most sites go from first call to live in a week. This is what that week looks like.</p>\r\n    <div class=\"steps\">\r\n      <div class=\"stepline\"><span class=\"day\">Day 1</span><div><h2>Discover</h2><p>A 45 minute call. Your goals, your customers, what the site has to do. You leave with a written scope and a fixed price the same day.</p></div></div>\r\n      <div class=\"stepline\"><span class=\"day\">Days 2 to 3</span><div><h2>Design</h2><p>Direction, layout and a clickable preview you approve on your phone and laptop. One round of changes is included.</p></div></div>\r\n      <div class=\"stepline\"><span class=\"day\">Days 4 to 6</span><div><h2>Build</h2><p>Clean code, fast pages, content in, tested on real devices. You get a link to watch it come together.</p></div></div>\r\n      <div class=\"stepline\"><span class=\"day\">Day 7</span><div><h2>Launch and care</h2><p>Domain, hosting and legal pages sorted. We go live together, then keep it sharp for a year, included.</p></div></div>\r\n    </div>\r\n    <h2>What we need from you</h2>\r\n    <p>Quick answers when we ask questions, about an hour a week for feedback, and your logo and any photos you want to keep. That is it.</p>\r\n    <div class=\"ask\">\r\n      <h2>Want to start the clock?</h2>\r\n      <p>Book the first call by email and we will send a couple of times.</p>\r\n      <div class=\"ask-row\"><a class=\"btn small\" data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Start a project <span class=\"arr\">&rarr;</span></a><a class=\"ask-alt\" data-sheet=\"questions\" role=\"button\" tabindex=\"0\">Questions people ask</a></div>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"get-in-touch\" data-title=\"Contact\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Contact\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Company</span>\r\n    <h1>Get in <em>touch</em></h1>\r\n    <p class=\"lead\">Tell us about your project. A real person replies within one business day.</p>\r\n    <form class=\"cform\" id=\"cform\" novalidate>\r\n      <label>Your name<input type=\"text\" name=\"name\" autocomplete=\"name\" required></label>\r\n      <label>Email<input type=\"email\" name=\"email\" autocomplete=\"email\" required></label>\r\n      <label>What do you need?\r\n        <select name=\"need\">\r\n          <option>A new website</option>\r\n          <option>A rebuild of my current site</option>\r\n          <option>Branding</option>\r\n          <option>A care plan for an existing site</option>\r\n          <option>Not sure yet</option>\r\n        </select>\r\n      </label>\r\n      <label>Tell us a bit about the business<textarea name=\"msg\" rows=\"4\" placeholder=\"What you sell, who buys it, and what the site should do\"></textarea></label>\r\n      <button class=\"btn\" type=\"submit\">Send it <span class=\"arr\">&rarr;</span></button>\r\n      <p class=\"cform-note\">This opens a ready made email in your mail app. Or just write to <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com</a>.</p>\r\n    </form>\r\n    <h2>Useful to include</h2>\r\n    <ul>\r\n      <li>Your current website, if there is one.</li>\r\n      <li>Two or three sites you like, from any industry.</li>\r\n      <li>When you need it live by.</li>\r\n    </ul>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a></div>\r\n  </div>\r\n</div>\r\n<div class=\"page\" id=\"questions\" data-title=\"FAQ\" role=\"dialog\" aria-modal=\"true\" aria-label=\"FAQ\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">FAQ</span>\r\n    <h1>Questions we <em>hear a lot</em></h1>\r\n    <p class=\"lead\">Straight answers to the things people ask before they hire us. If yours is not here, email and we will answer it the same day.</p>\r\n    <div class=\"group\">Money and timing</div>\r\n    <h2>How much does a website cost?</h2>\r\n    <p>It depends on what the site has to do. A four or five page site for a local business is a very different job from a shop with two hundred products. What stays the same is how we price it: you get a short discovery call, then a fixed written quote. The price you approve is the price you pay. No hourly surprises, no \"that was out of scope\" invoice at the end.</p>\r\n    <h2>How long does a project take?</h2>\r\n    <p>Most sites go live within a week of kickoff once the content is ready. Bigger builds, like a shop with a few hundred products, take longer, and you get a dated timeline before we start. If anything moves it, you hear about it the same day, not at the deadline.</p>\r\n    <h2>How do payments work?</h2>\r\n    <p>Half when you approve the proposal, half when the site goes live. Care plans are billed monthly. Everything is on a normal invoice you can pay by card or transfer.</p>\r\n    <h2>Do you do payment plans?</h2>\r\n    <p>For bigger projects, yes. Tell us on the discovery call and we will split it into stages that line up with the work.</p>\r\n    <div class=\"group\">Working together</div>\r\n    <h2>What's the difference between design and development?</h2>\r\n    <p>Design is how the site looks and flows: layout, type, colour, the order things appear in, what a visitor is meant to do next. Development is the code that makes that real in a browser. At a lot of agencies those are two teams and a handoff in between. Here the same people do both, so the thing you approved is the thing that gets built.</p>\r\n    <h2>What do we need to give you?</h2>\r\n    <p>Your logo if you have one, any photos or writing you want to keep, and about an hour a week for feedback. If you have no logo or no copy, that is fine too, branding and copywriting are things we do. The only thing we really need from you is quick answers when we ask questions.</p>\r\n    <h2>Will you write the words?</h2>\r\n    <p>Yes. Most of our clients hand us rough notes or a phone call and we turn that into the copy. You approve every line before it goes live.</p>\r\n    <h2>Do you do the photos?</h2>\r\n    <p>We source stock where it fits and can arrange a photographer for anything that needs to be real, like your team, your premises or your products. Photo costs are quoted separately so you can decide.</p>\r\n    <h2>Can we see it before it is built?</h2>\r\n    <p>Always. You get a clickable design to poke at on your phone and laptop before a line of code is written. Changes are cheap at that stage, so that is where we do most of the tweaking.</p>\r\n    <h2>What if I already have a site?</h2>\r\n    <p>We look at what is working, keep whatever is genuinely good, and rebuild the rest. Your search rankings and old links get carried across so you do not lose traffic on launch day.</p>\r\n    <div class=\"group\">After launch</div>\r\n    <h2>Who owns the website?</h2>\r\n    <p>You do. The domain, the code and the content are in your name from day one. If you ever leave, you take everything with you, and we hand over every login we hold.</p>\r\n    <h2>What happens after launch?</h2>\r\n    <p>Every project comes with a year of care included. That means updates, small fixes, security patches and a short monthly report in plain English. After the year you can carry on with a care plan or take the keys and run it yourself.</p>\r\n    <h2>Where is the site hosted?</h2>\r\n    <p>We set up hosting, the domain, email forwarding and the SSL certificate as part of the build, so nothing is left on your to do list. The accounts are in your name, we just manage them.</p>\r\n    <h2>What about the legal pages?</h2>\r\n    <p>Privacy policy, terms and cookie notice come with the site, written for your business, not copied from a template you have to decode. You check the details, we put them live.</p>\r\n    <h2>Can I edit the site myself?</h2>\r\n    <p>Yes. Text, images and blog posts are editable without touching code, and we walk you through it on a short call at handover. Anything bigger, send it to us.</p>\r\n    <h2>Can't AI just build my website?</h2>\r\n    <p>AI tools can put out a decent looking page in minutes, and we use them wherever they speed us up. What they cannot do is know your market, your customers, or why a visitor should pick you over the place down the road. That judgement is the job. The tools are just tools.</p>\r\n    <div class=\"ask\">\r\n      <h2>Still got a question?</h2>\r\n      <p>Email <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com</a> and a real person replies within one business day.</p>\r\n    </div>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a><a data-sheet=\"privacy\" role=\"button\" tabindex=\"0\">Privacy</a><a data-sheet=\"terms\" role=\"button\" tabindex=\"0\">Terms</a><a data-sheet=\"cookies\" role=\"button\" tabindex=\"0\">Cookies</a></div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"page\" id=\"privacy\" data-title=\"Privacy policy\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Privacy policy\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Legal</span>\r\n    <h1>Privacy <em>policy</em></h1>\r\n    <p class=\"updated\">Last updated: 30 September 2026. Words <mark>highlighted like this</mark> need your details before this goes live.</p>\r\n\r\n    <h2>Who we are</h2>\r\n    <p>Pinsite is a web design agency operated by <mark>[legal company name]</mark>, <mark>[registered address]</mark>. When we say \"we\" or \"us\" in this policy we mean that company. You can reach us about anything in here at <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com</a>.</p>\r\n\r\n    <h2>What we collect</h2>\r\n    <p>We keep it to what we actually need:</p>\r\n    <ul>\r\n      <li><strong>Things you send us.</strong> Your name, email address, company name and whatever you write when you email us or fill in the contact form.</li>\r\n      <li><strong>Project information.</strong> If you become a client, the content, images, logins and business details you share so we can build and maintain your site.</li>\r\n      <li><strong>Basic site usage.</strong> Pages visited, rough location (country or city), device type and how you found us. This comes from our analytics tool and is aggregated, not tied to you by name.</li>\r\n    </ul>\r\n\r\n    <h2>How we use it</h2>\r\n    <ul>\r\n      <li>To reply to you and scope a project.</li>\r\n      <li>To design, build, host and maintain sites for clients.</li>\r\n      <li>To send invoices and keep the paperwork straight.</li>\r\n      <li>To understand which parts of our own site are useful and which are not.</li>\r\n    </ul>\r\n    <p>We do not sell your details and we do not add you to a newsletter unless you ask for one.</p>\r\n\r\n    <h2>Who we share it with</h2>\r\n    <p>Only with services we need to run the business: email and cloud storage providers, our hosting and domain partners, our accounting software and payment processor, and analytics. Each of them is bound by their own privacy terms and only gets what they need to do their job. We will share information if the law requires it.</p>\r\n\r\n    <h2 id=\"cookies\">Cookies</h2>\r\n    <p>This site uses a small number of cookies, explained in full in the <a data-sheet=\"cookies\" role=\"button\" tabindex=\"0\">cookie policy</a>. Short version: a couple of essential ones that make the site work, and analytics that only run if you accept them.</p>\r\n\r\n    <h2>How long we keep it</h2>\r\n    <p>Enquiries we have not turned into projects are deleted after 12 months. Client files are kept for the length of the project and any care plan, plus what tax and accounting law makes us keep, then removed.</p>\r\n\r\n    <h2>Your rights</h2>\r\n    <p>You can ask us what we hold about you, ask us to correct it, or ask us to delete it. Email <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com</a> and we will sort it within 30 days. If you are in the UK or EU you also have the right to complain to your data protection authority.</p>\r\n\r\n    <h2>Changes</h2>\r\n    <p>If we change this policy we will update the date at the top. Anything significant, we will tell current clients directly.</p>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a><a data-sheet=\"privacy\" role=\"button\" tabindex=\"0\">Privacy</a><a data-sheet=\"terms\" role=\"button\" tabindex=\"0\">Terms</a><a data-sheet=\"cookies\" role=\"button\" tabindex=\"0\">Cookies</a></div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"page\" id=\"terms\" data-title=\"Terms of service\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Terms of service\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Legal</span>\r\n    <h1>Terms of <em>service</em></h1>\r\n    <p class=\"updated\">Last updated: 30 September 2026. Words <mark>highlighted like this</mark> need your details before this goes live.</p>\r\n\r\n    <h2>The short version</h2>\r\n    <p>These terms cover use of this website and the general basis on which Pinsite, operated by <mark>[legal company name]</mark>, does work for clients. Every project also gets its own written proposal, and where the two disagree the proposal wins.</p>\r\n\r\n    <h2>Using this site</h2>\r\n    <p>The content on this site, including the design, text, images and code, belongs to us or our clients and is here so you can find out about our work. You are welcome to link to it. Please do not copy the site or lift work from it without asking.</p>\r\n    <p>The work shown in our portfolio was built for real clients and is shown with their agreement. It belongs to them.</p>\r\n\r\n    <h2>Proposals and quotes</h2>\r\n    <p>Every project starts with a written proposal that sets out the scope, the price, the timeline and what we need from you. A quote is valid for 30 days. Work starts once the proposal is accepted and the first invoice is paid.</p>\r\n\r\n    <h2>Payment</h2>\r\n    <p>Unless the proposal says otherwise, projects are billed <mark>[50% upfront and 50% on launch]</mark>. Care plans are billed monthly in advance. Invoices are due within <mark>[14]</mark> days. If an invoice is more than 30 days late we may pause work until it is settled.</p>\r\n\r\n    <h2>Your part</h2>\r\n    <p>Projects move quickly when content, feedback and approvals arrive on time. If a project stalls on your side for more than <mark>[30]</mark> days we may invoice for the work completed so far and reschedule the rest.</p>\r\n    <p>You confirm that anything you give us to use on your site, such as text, photos, logos and fonts, is yours to use or properly licensed.</p>\r\n\r\n    <h2>Revisions</h2>\r\n    <p>Each proposal includes a set number of revision rounds. Changes beyond that, or changes to the agreed scope, are quoted separately before we do them.</p>\r\n\r\n    <h2>Ownership</h2>\r\n    <p>Once the final invoice is paid, the finished site is yours: the design, the content and the code we wrote for it. We keep the right to show the work in our portfolio and to reuse general tools, components and know-how that are not specific to your business. Third party items, such as fonts, stock images and plugins, stay under their own licences.</p>\r\n\r\n    <h2>Hosting, care plans and cancellation</h2>\r\n    <p>The first year of care is included with every build. After that, care plans run month to month and can be cancelled with <mark>[30]</mark> days notice by email. If you leave, we will hand over a full copy of your site and any logins we hold. We are not responsible for a site once it is hosted or edited outside our care.</p>\r\n\r\n    <h2>What we are not responsible for</h2>\r\n    <p>We build sites carefully and test them before launch, but we cannot promise a particular sales result, search ranking or that a site will be free of every possible error. Our total liability for any project is limited to the amount you paid us for it. We are not liable for indirect losses such as lost profit.</p>\r\n\r\n    <h2>Law</h2>\r\n    <p>These terms are governed by the laws of <mark>[country or state]</mark> and any dispute goes to the courts there.</p>\r\n\r\n    <h2>Contact</h2>\r\n    <p>Questions about these terms: <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com</a>.</p>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a><a data-sheet=\"privacy\" role=\"button\" tabindex=\"0\">Privacy</a><a data-sheet=\"terms\" role=\"button\" tabindex=\"0\">Terms</a><a data-sheet=\"cookies\" role=\"button\" tabindex=\"0\">Cookies</a></div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"page\" id=\"cookies\" data-title=\"Cookie policy\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Cookie policy\">\r\n  <div class=\"sheet-bar\"><a class=\"logo\" role=\"button\" tabindex=\"0\" data-close><b class=\"mk\" aria-hidden=\"true\"></b>pinsite</a><button class=\"sheet-close\" type=\"button\" aria-label=\"Close\">&times;</button></div>\r\n  <div class=\"pwrap\">\r\n    <span class=\"eyebrow\">Legal</span>\r\n    <h1>Cookie <em>policy</em></h1>\r\n    <p class=\"updated\">Last updated: 30 September 2026. Words <mark>highlighted like this</mark> need your details before this goes live.</p>\r\n\r\n    <h2>What cookies are</h2>\r\n    <p>A cookie is a small text file a website stores on your device so it can remember something about your visit. Most sites use a few. This one uses fewer than most.</p>\r\n\r\n    <h2>The cookies we use</h2>\r\n    <table>\r\n      <tr><th>Cookie</th><th>What it does</th><th>Lasts</th></tr>\r\n      <tr><td>Essential</td><td>Keeps the site working, remembers a form you started, stores your cookie choice. Cannot be switched off.</td><td>Up to 12 months</td></tr>\r\n      <tr><td>Analytics (<mark>[provider]</mark>)</td><td>Tells us which pages get read and roughly where visitors come from, in aggregate. Only set if you accept it.</td><td>Up to 24 months</td></tr>\r\n    </table>\r\n    <p>We do not use advertising cookies and we do not sell or share cookie data with advertisers.</p>\r\n\r\n    <h2>Third parties</h2>\r\n    <p>Fonts are loaded from Google Fonts, which may log a request to fetch them. Embedded videos, if any, come from YouTube and may set their own cookies when you play them. Their policies apply to those.</p>\r\n\r\n    <h2>How to manage them</h2>\r\n    <p>You can change your choice at any time using the cookie link in the footer, or delete and block cookies in your browser settings. Blocking the essential cookies may stop parts of the site working. Blocking analytics changes nothing for you.</p>\r\n\r\n    <h2>Questions</h2>\r\n    <p>Email <a href=\"mailto:pinsite74@gmail.com\">pinsite74@gmail.com</a>. More on how we handle information is in the <a data-sheet=\"privacy\" role=\"button\" tabindex=\"0\">privacy policy</a>.</p>\r\n    <div class=\"page-foot\"><a data-sheet=\"web-design\" role=\"button\" tabindex=\"0\">Web design</a><a data-sheet=\"development\" role=\"button\" tabindex=\"0\">Development</a><a data-sheet=\"branding\" role=\"button\" tabindex=\"0\">Branding</a><a data-sheet=\"care-plans\" role=\"button\" tabindex=\"0\">Care plans</a><a data-sheet=\"studio\" role=\"button\" tabindex=\"0\">About</a><a data-sheet=\"builds\" role=\"button\" tabindex=\"0\">Work</a><a data-sheet=\"how-we-work\" role=\"button\" tabindex=\"0\">Process</a><a data-sheet=\"questions\" role=\"button\" tabindex=\"0\">FAQ</a><a data-sheet=\"get-in-touch\" role=\"button\" tabindex=\"0\">Contact</a><a data-sheet=\"privacy\" role=\"button\" tabindex=\"0\">Privacy</a><a data-sheet=\"terms\" role=\"button\" tabindex=\"0\">Terms</a><a data-sheet=\"cookies\" role=\"button\" tabindex=\"0\">Cookies</a></div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"scroll-blur\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i><i></i></div>\r\n\r\n<script>\r\n// load choreography\r\nwindow.addEventListener('load',()=>document.body.classList.add('ready'));\r\n// nav background on scroll\r\nconst nav=document.getElementById('nav');\r\naddEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>10),{passive:true});\r\n// work carousel — add real shots by giving any project an img:'url'\r\nconst IMGS={\n  c1:{src:'/projects/c1.webp',w:735,h:490},\n  c2:{src:'/projects/c2.webp',w:760,h:434},\n  c3:{src:'/projects/c3.webp',w:736,h:414},\n  c4:{src:'/projects/c4.webp',w:760,h:430},\n  c5:{src:'/projects/c5.webp',w:736,h:414},\n  c6:{src:'/projects/c6.webp',w:585,h:328},\n  c7:{src:'/projects/c7.webp',w:754,h:429},\n  c8:{src:'/projects/c8.webp',w:541,h:283},\n  c9:{src:'/projects/c9.webp',w:760,h:346},\n  c10:{src:'/projects/c10.webp',w:477,h:337},\n  c11:{src:'/projects/c11.webp',w:760,h:424},\n  c12:{src:'/projects/c12.webp',w:736,h:480},\n  c13:{src:'/projects/c13.webp',w:760,h:472},\n  c14:{src:'/projects/c14.webp',w:647,h:378}\n};\r\nconst projects={\r\n  top:[\r\n    {n:'Cosmetics brand',img:IMGS.c1},\r\n    {n:'Yoga studio',img:IMGS.c11},\r\n    {n:'Watch store',img:IMGS.c2},\r\n    {n:'Dental practice',img:IMGS.c9},\r\n    {n:'Skincare brand',img:IMGS.c13},\r\n    {n:'Road works company',img:IMGS.c7},\r\n    {n:'Body care brand',img:IMGS.c3}\r\n  ],\r\n  bottom:[\r\n    {n:'Web3 platform',img:IMGS.c5},\r\n    {n:'Artisan bakery',img:IMGS.c14},\r\n    {n:'Sneaker store',img:IMGS.c8},\r\n    {n:'Dental clinic',img:IMGS.c4},\r\n    {n:'Clothing store',img:IMGS.c12},\r\n    {n:'Pizza restaurant',img:IMGS.c10},\r\n    {n:'Fashion retail',img:IMGS.c6}\r\n  ]\r\n};\r\nconst tile=p=>`<article class=\"proj\">${p.img?`<img class=\"thumb\" src=\"${p.img.src}\" width=\"${p.img.w}\" height=\"${p.img.h}\" alt=\"${p.n} website homepage\" loading=\"lazy\" decoding=\"async\">`:`<div class=\"thumb ${p.t}\" aria-hidden=\"true\"></div>`}</article>`;\r\ndocument.querySelectorAll('.car-row').forEach(row=>{\r\n  const set=projects[row.dataset.row].map(tile).join('');\r\n  row.innerHTML=`<div class=\"car-set\">${set}</div><div class=\"car-set\" aria-hidden=\"true\">${set}</div>`;\r\n});\r\n// results: roll the numbers when the section comes into view\r\n(()=>{\r\n  const grid=document.querySelector('.res-grid');\r\n  if(!grid)return;\r\n  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;\r\n  grid.querySelectorAll('.odo').forEach(o=>{\r\n    const v=o.textContent.trim();\r\n    o.setAttribute('aria-label',v);\r\n    if(reduce)return;\r\n    o.classList.add('rolled');\r\n    o.innerHTML=[...v].map((ch,i)=>{\r\n      if(!/\\d/.test(ch))return `<span aria-hidden=\"true\">${ch}</span>`;\r\n      const strip=[...'01234567890123456789'].map(d=>`<span>${d}</span>`).join('');\r\n      return `<span class=\"dg\" aria-hidden=\"true\" style=\"--d:${10+ +ch}\"><i style=\"transition-delay:${i*90}ms\">${strip}</i></span>`;\r\n    }).join('');\r\n  });\r\n  const go=()=>grid.querySelectorAll('.odo').forEach(o=>o.classList.add('go'));\r\n  if(reduce||!('IntersectionObserver' in window)){grid.classList.add('in');go();return}\r\n  new IntersectionObserver((es,io)=>{es.forEach(e=>{if(e.isIntersecting){setTimeout(go,120);io.disconnect()}})},{threshold:.35}).observe(grid);\r\n})();\r\n// sheets: the footer links slide a page up over the site. close with the x, the backdrop, escape, or any other link.\r\n// the url hash is kept in sync where the browser allows it, and quietly skipped where it does not (sandboxed previews)\r\n(()=>{\r\n  const pages=[...document.querySelectorAll('.page')];\r\n  if(!pages.length)return;\r\n  const baseTitle=document.title;\r\n  const setHash=h=>{try{history.pushState(null,'',h)}catch(e){}};\r\n  const clearHash=()=>{try{if(location.hash)history.replaceState(null,'',location.pathname+location.search)}catch(e){}};\r\n  const show=id=>{\r\n    const page=pages.find(p=>p.id===id)||null;\r\n    pages.forEach(p=>{const on=p===page;p.classList.toggle('active',on);if(on)p.scrollTop=0});\r\n    document.body.classList.toggle('sheet-open',!!page);document.documentElement.classList.toggle('sheet-open',!!page);\r\n    if(page){document.title=page.dataset.title+' | Pinsite';page.querySelector('.sheet-close').focus({preventScroll:true})}\r\n    else document.title=baseTitle;\r\n  };\r\n  const close=()=>{clearHash();show(null)};\r\n  document.querySelectorAll('.sheet-close').forEach(b=>b.addEventListener('click',close));\r\n  document.querySelector('.sheet-backdrop').addEventListener('click',close);\r\n  addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('sheet-open'))close()});\r\n  // links inside a sheet that point at a section of the site close the sheet first, then scroll\r\n  pages.forEach(p=>p.querySelectorAll('a[href^=\"#\"]').forEach(a=>{\r\n    const id=a.getAttribute('href').slice(1);\r\n    if(!pages.some(x=>x.id===id))a.addEventListener('click',e=>{e.preventDefault();close();const t=document.getElementById(id);if(t)t.scrollIntoView({behavior:'smooth'})});\r\n  }));\r\n  // anything with data-sheet opens that sheet. no href on purpose, so hosted previews don't treat it as leaving the page\r\n  const open=id=>{setHash('#'+id);show(id)};\r\n  document.addEventListener('click',e=>{\r\n    const t=e.target.closest('[data-sheet],[data-close]');if(!t)return;\r\n    e.preventDefault();\r\n    if(t.hasAttribute('data-close')){close();window.scrollTo({top:0,behavior:'smooth'})}\r\n    else open(t.dataset.sheet);\r\n  });\r\n  document.addEventListener('keydown',e=>{\r\n    if(e.key!=='Enter'&&e.key!==' ')return;\r\n    const t=e.target.closest&&e.target.closest('[data-sheet],[data-close]');if(!t)return;\r\n    e.preventDefault();t.click();\r\n  });\r\n  const fromHash=()=>show(location.hash.slice(1));\r\n  addEventListener('hashchange',fromHash);\r\n  addEventListener('popstate',fromHash);\r\n  fromHash();\r\n})();\r\n// the work sheet builds its grid from the same project list as the carousel\r\n(()=>{\r\n  const g=document.getElementById('workGrid');if(!g)return;\r\n  const all=[...projects.top,...projects.bottom];\r\n  g.innerHTML=all.map(p=>`<figure><img src=\"${p.img.src}\" width=\"${p.img.w}\" height=\"${p.img.h}\" alt=\"${p.n} website homepage\" loading=\"lazy\" decoding=\"async\"><figcaption><b>${p.n}</b>Design, build and care</figcaption></figure>`).join('');\r\n})();\r\n// contact form: no server needed, it opens a filled in email\r\n(()=>{\r\n  const f=document.getElementById('cform');if(!f)return;\r\n  f.addEventListener('submit',e=>{\r\n    e.preventDefault();\r\n    const d=new FormData(f);\r\n    const name=(d.get('name')||'').trim(),email=(d.get('email')||'').trim();\r\n    if(!name||!email||!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email)){f.classList.remove('shake');void f.offsetWidth;f.classList.add('shake');(name?f.email:f.name).focus();return}\r\n    const subject=encodeURIComponent(`Project enquiry from ${name}`);\r\n    const body=encodeURIComponent(`Hi Pinsite,\\n\\nI need: ${d.get('need')}\\n\\n${(d.get('msg')||'').trim()}\\n\\n${name}\\n${email}`);\r\n    const url=`mailto:pinsite74@gmail.com?subject=${subject}&body=${body}`;\r\n    try{location.href=url}catch(err){window.open(url,'_blank')}\r\n  });\r\n})();\r\n// hero word rotator\r\nconst swapEl=document.getElementById('swap');\r\nconst swapWords=['slow','dated','invisible','ugly','DIY','generic'];\r\nlet swapI=0;\r\nconst swapSlot=document.getElementById('swapChip');\r\nconst lockSlot=()=>{\r\n  if(!swapEl||!swapSlot)return;\r\n  const m=document.createElement('i');m.className='sww';\r\n  m.style.cssText='position:absolute;visibility:hidden;white-space:nowrap;padding:0;margin:0';\r\n  swapSlot.appendChild(m);\r\n  let max=0;swapWords.forEach(w=>{m.textContent=w;max=Math.max(max,m.offsetWidth)});\r\n  m.remove();\r\n  const fs=parseFloat(getComputedStyle(swapEl).fontSize);\r\n  if(fs)swapSlot.style.minWidth=(max/fs)+'em';\r\n};\r\nlockSlot();\r\ndocument.fonts.ready.then(lockSlot);\r\nif(swapEl&&!matchMedia('(prefers-reduced-motion: reduce)').matches){\r\n  setInterval(()=>{\r\n    swapEl.classList.add('out');\r\n    setTimeout(()=>{\r\n      swapI=(swapI+1)%swapWords.length;\r\n      swapEl.textContent=swapWords[swapI];\r\n      swapEl.classList.remove('out');\r\n      swapEl.classList.add('in');\r\n      requestAnimationFrame(()=>requestAnimationFrame(()=>swapEl.classList.remove('in')));\r\n    },290);\r\n  },2200);\r\n}\r\n// scroll reveals (stagger handled in CSS)\r\nconst io=new IntersectionObserver(es=>es.forEach(e=>{\r\n  if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}\r\n}),{threshold:.18});\r\ndocument.querySelectorAll('[data-reveal],[data-stagger]').forEach(el=>io.observe(el));\r\ndocument.getElementById('yr').textContent=new Date().getFullYear();\r\n</script>\r\n</body>\r\n</html>\r\n";
